'use strict';
// Generated by build-pwa.py. Each release installs a complete matching shell.
const CACHE_PREFIX=`quantity-table:${self.registration.scope}:`;
const CACHE_NAME=CACHE_PREFIX+'d61f8f3089748235';
const SHELL=[
  "./",
  "./index.html",
  "./styles.css",
  "./catalog.js",
  "./pdf.js",
  "./app.js",
  "./pwa.js",
  "./manifest.webmanifest",
  "./assets/sucoot-logo.png",
  "./assets/pwa/icon-192.png",
  "./assets/pwa/icon-512.png",
  "./assets/pwa/apple-touch-icon.png"
];
const shellURLs=new Set(SHELL.map(path=>new URL(path,self.registration.scope).href));
self.addEventListener('install',event=>{
  event.waitUntil(caches.open(CACHE_NAME).then(cache=>cache.addAll(SHELL.map(path=>new Request(new URL(path,self.registration.scope),{cache:'reload'})))));
  // Updates wait until the user chooses "更新並重新開啟"; no forced reload.
});
self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    const names=await caches.keys();await Promise.all(names.filter(name=>name.startsWith(CACHE_PREFIX)&&name!==CACHE_NAME).map(name=>caches.delete(name)));
    await self.clients.claim();
  })());
});
self.addEventListener('message',event=>{if(event.data?.type==='SKIP_WAITING')self.skipWaiting();});
self.addEventListener('fetch',event=>{
  if(event.request.method!=='GET')return;
  const url=new URL(event.request.url);url.search='';url.hash='';
  if(!shellURLs.has(url.href))return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE_NAME),hit=await cache.match(url.href);
    if(hit)return hit;
    // Only known public application assets are retained; form data never uploads.
    const response=await fetch(event.request);if(response.ok)await cache.put(url.href,response.clone());return response;
  })());
});
